INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Mines II: Buried Treasure', 'In 2000, Songbird Productions produced a sequel, Crystal Mines II: Buried Treasure on CD-ROM for Microsoft Windows. This CD-ROM required the original game and a Lynx to PC serial cable to run, allowing the editing and creation of all new levels. This was followed in 2003 by a cartridge release of Crystal Mines II: Buried Treasure with the original 181 levels and 125 new levels.' FROM games WHERE igdb_id = 64564 ON CONFLICT (game_id, language_code) DO NOTHING;
