INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sentou Yousei Yukikaze: Yousei no Mau Sora', 'Flight combat game based on popular novel and anime series. Players jump into the cockpit of futuristic jet planes and duke it out in the skies with the latest hi-tech weaponry. The main Mission mode tells a coherent story based on the anime and lets players progress through connected scenarios. There is also a Versus mode for split-screen two-player battles, and the Extra mode that duplicates the feel of traditional flight combat arcade games where players compete for the highest score. Supports Dolby Digital 5.1 surround sound and the Japanese Top Gun flight stick. Released only in Japan.' FROM games WHERE igdb_id = 153607 ON CONFLICT (game_id, language_code) DO NOTHING;
