INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Genesis Evangelion: The Iron Maiden 2nd', 'Neon Genesis Evangelion: Girlfriend of Steel 2nd (新世紀エヴァンゲリオン鋼鉄のガールフレンド 2nd Shinseiki Evangerion Kōtetsu no Gārufurendo 2nd, lit. "Neon Genesis Evangelion Girlfriend of Steel 2nd"), subtitled in English Neon Genesis Evangelion: Iron Maiden 2nd, is a Gainax-produced adventure anime-style video game, and manga based on that game, set in the alternate universe seen in episode 26 of Neon Genesis Evangelion. The player controls Shinji Ikari, the hero of the original Evangelion series, as he navigates his home, school, and social life in a now-peaceful "Tokyo-3".' FROM games WHERE igdb_id = 75879 ON CONFLICT (game_id, language_code) DO NOTHING;
