INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bumer: Sorvannye bashni', 'Bumer: Sorvannye bashni is an arcade first-person shooter with racing elements. It is based on the Russian movie Bumer, but as a free interpretation. The gameplay consists of racing, gang chases and gunfights. Racing levels are similar to sprint races from the Need for Speed series. The player races point-to-point tracks and needs to finish before an opponent.
