INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pochi and Nyaa', 'Pochi and Nyaa is a puzzle game made by Taito (Makers of Puzzle Bobble/Bust-A-Move) and Aiky. The story behind it is that in every 1000 years there is a Tournament held by the animal gods Pochi (the Dog) and Nyaa (the Cat) in decision who will be the top star for the next millennium, although they need the power of Earth''s people to do so. The gameplay is similar to Super Puzzle Fighter and Puyo Pop, but with a few differences.' FROM games WHERE igdb_id = 40188 ON CONFLICT (game_id, language_code) DO NOTHING;
