INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hudson Selection Vol. 2: Star Soldier', 'The best of breed scrolling shooter of the Nintendo Entertainment System returns in this smash wireless hit! This is a sole warrior''s mission to rid the galaxy of the sinister Star Brain life forms that now control 16 huge areas of space. It''s going to be tough but your starship, the Caesar, can pack some decent firepower so you can become a true Star Soldier of the galaxy.' FROM games WHERE igdb_id = 43207 ON CONFLICT (game_id, language_code) DO NOTHING;
