INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Borussia Dortmund Club Football', 'Borussia Dortmund Club Football is a club-specific edition of Codemasters’ football simulation series, designed to deliver an immersive experience tailored to fans of Borussia Dortmund. Players compete in a faithful replica of Signal Iduna Park, complete with authentic kits, chants, and crowd atmospherics. The game includes multiple modes such as Domestic Season, European Super League, and Custom Tournaments, and features a player editor that lets fans insert themselves into the squad.' FROM games WHERE igdb_id = 267884 ON CONFLICT (game_id, language_code) DO NOTHING;
