INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Simulator ＋ Densha de Go!: Tokyo Kyuukou-hen', 'Train Simulator + Densha de GO!: Tokyo Kyuukou-hen is an train driving simulation game. It is a crossover between Ongakukan''s Train SImulator series and Taito''s Densha de GO! series. It uses full-motion video from the train driver''s perspective and features two gameplay modes, with the display, controls, and gameplay mechanics of either series. It features three routes from the Tokyo Express Electric Railway (better known as Tokyu): the Toyoko Line, the Den-en-toshi Line, and the Oimachi Line.' FROM games WHERE igdb_id = 92251 ON CONFLICT (game_id, language_code) DO NOTHING;
