INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mistmare', 'Mistmare is a role-playing game set in an alternate reality of the year 1996, where the industrial revolution never took place. You play as the monk Isidor, in a medieval looking Europe, using magic based on sounds to fight wrongdoers and monsters and to restore order to the fragile world around you. A mystical, deadly fog has separated the northern parts of Europe from the southern and one of your main tasks is to solve the mysteries surrounding the phenomenon.' FROM games WHERE igdb_id = 78398 ON CONFLICT (game_id, language_code) DO NOTHING;
