INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dinosaur Hunting: Ushinawareta Daichi', 'On the highlands of Guiana in the Amazon interior lives dinosaurs! The largest rescue operation in human history is about to commence. But the Guiana highlands are showing signs of volcanic activity. The dinosaurs that have defied fate and survived until now are suddenly facing extinction. They must be transported to a new location at all costs.' FROM games WHERE igdb_id = 85950 ON CONFLICT (game_id, language_code) DO NOTHING;
