INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Fighter 10th Anniversary', 'Virtua Fighter 10th Anniversary is a combination of the original Virtua Fighter arcade title, with Virtua Fighter 4: Evolution, for PlayStation 2. In North America, Virtua Fighter 10th Anniversary was included in Virtua Fighter 4: Evolution. In Japan, Virtua Fighter 10th Anniversary shipped as part of a box set, including an art book and DVD with Virtua Fighter history, under the title of "Virtua Fighter 10th Anniversary ~Memory of Decade~". In Europe, Virtua Fighter 10th Anniversary was only available as a promotional item, and was never sold at retail.' FROM games WHERE igdb_id = 1553 ON CONFLICT (game_id, language_code) DO NOTHING;
