INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomic Cannon', 'Atomic Cannon is a fun arcade game that is easy to learn but difficult to master. In this strategic tank artillery duel you battle against computers or friends on 25 different landscapes. Players take turns aiming and firing at each other with over 100 weapons of mass destruction including nuclear bombs.' FROM games WHERE igdb_id = 227826 ON CONFLICT (game_id, language_code) DO NOTHING;
