INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Jack: Code of the Samurai', 'Placed into enemy territory, Samurai Jack must use his wits and mastery of ancient weapons to navigate 3 treacherous levels to defeat Aku! In addition to his sword, Jack can also unlock 6 additional secret weapons including: ninja stars, flaming arrows, a mace, shields, a longsword, and metal gauntlets.' FROM games WHERE igdb_id = 327029 ON CONFLICT (game_id, language_code) DO NOTHING;
