INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Cartoon Summer Resort', 'Cartoon Cartoon Summer Resort is an open-world, exploring game, in which you control a character (all four first appeared in failed pilot cartoons) and do various tasks for different characters from Cartoon Network (specifically Cartoon Cartoon shows). Doing these tasks will earn you items which are used to give to other characters to complete the episode.' FROM games WHERE igdb_id = 130744 ON CONFLICT (game_id, language_code) DO NOTHING;
