INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Wrestling: Don''t Try This at Home', 'Backyard Wrestling allows you to step out of the staleness of the wrestling genre, and into a groundbreaking new world of open ended gameplay. Punish your opponent in highly interactive sprawling environments implementing instruments of pain like thumbtacks, barbed wire, light bulbs, stop signs, baseball bats, tables, fire as well as the environment itself. Prepare yourself to endure inhuman amounts of pain, and take incredible risks, as you leap from breathtaking heights to beat your opponent, and be crowned "The King Of Hardcore".' FROM games WHERE igdb_id = 5734 ON CONFLICT (game_id, language_code) DO NOTHING;
