INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu Yu Hakusho: Spirit Detective', 'Yu Yu Hakusho tells the story of Yusuke Urameshi, a character who battles evil in both the living and spirit worlds. In Spirit Detective, you''ll guide Yusuke through various adventures taken from the animated TV series. The game chronicles the first third of the hero''s 112-episode journey. As any one of six characters, you''ll battle evil enemies with signature attacks and weapons. Journey through the spirit world, conquer Yusuke''s enemies, and master each quest to become a true spirit detective.' FROM games WHERE igdb_id = 6696 ON CONFLICT (game_id, language_code) DO NOTHING;
