INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hugo: Bukkazoom', 'Hugo: Bukkazoom! is a 3D racing game based starring Hugo the TV Troll, a popular cartoon character on Danish television. In this game Hugo is shrunk to the size of little green creatures called greenflies. He must race a kart through marshes, deserts and various landscapes. The circuits have checkpoints, upgrades and a scoring system open to different possible strategies. Both single-player and multiplayer games for up to two players are supported.' FROM games WHERE igdb_id = 165052 ON CONFLICT (game_id, language_code) DO NOTHING;
