INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reel Fishing III', 'Do you remember the very first time you went fishing? The fresh air...the soothing sounds of nature around you...the tranquility of the water. Reel Fishing III is a return to nature fishing! Whether you a seasoned veteran or have yet to cast your first line, Reel Fishing III will make it possible to experience fishing as it was meant to be...as it should be...in mother nature. Experience a magnificent 3-Dimensional fishing adventure with beautiful environments, lifelike fish and soothing environmental sounds!' FROM games WHERE igdb_id = 43390 ON CONFLICT (game_id, language_code) DO NOTHING;
