INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Enduring Pretzel', 'Operation Enduring Pretzel is a Czech indie FPS game where you infiltrate a government building taken over by terrorists. You progress through different floors (Garden, Ground Floor, 1st Floor, Basement), collecting keys, documents, weapons (like COLT, submachine gun, and MINIGUN), and battling enemies.' FROM games WHERE igdb_id = 341955 ON CONFLICT (game_id, language_code) DO NOTHING;
