INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MegaMan NT Warrior Advanced PET', 'Personal Terminal Based on the popular animé video game and the new MegaMan NT Warrior cartoon series about the year 200X, the Network Age where each person carries a portable communications interface device called a PET or personal terminal, that contains an artificial intelligence program, or NetNavi, designed to navigate the worldwide information network for their respective human, or NetOperator. Be a player with your own PET! Connect with another player and load battle chips into your PET to aid your NetNavi as he battles other NetNavis. But watch out for viruses! Comes with three battle chips.' FROM games WHERE igdb_id = 336716 ON CONFLICT (game_id, language_code) DO NOTHING;
