INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pazunin: Uminin no Puzzle de Nimu', 'Pazunin - Uminin no Puzzle de Nimu is a localized version of the GBA game Gem Smashers, released a few months earlier, with its graphics replaced by Uminin assets. A later variant using the M&M’s mascots was also produced. While officially described as an action puzzle game, its mechanics are closer to a block-breaking game. It features multiple play modes and supports manual saving.' FROM games WHERE igdb_id = 356453 ON CONFLICT (game_id, language_code) DO NOTHING;
