INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sekai Saikyou Ginsei Igo 3', 'Sekai Saikyou Ginsei Igo 3 is a board game that offers authentic igo (weiqi) experience. Apart from matching with the computer, 2 player matching is also supported. Player can pick from three types of board: 9x9, 13x13 and 19x19, and set the game as even or with up to nine handicap stones. Jump into the world of igo today!' FROM games WHERE igdb_id = 347157 ON CONFLICT (game_id, language_code) DO NOTHING;
