INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enigmo', 'Enigmo is an award-winning unique 3D puzzle game where you manipulate slides, bumpers, accelerators and other pieces to control streams of flowing liquid. Liquids (water, oil, and lava) fall from ''droppers'' and will bounce around the walls of a puzzle. You move and rotate the various puzzle pieces in order to divert the flow of the falling droplets so that they can reach their target. The faster you complete each level, the more bonuses you will receive, the higher position in the high scores table you get.' FROM games WHERE igdb_id = 92750 ON CONFLICT (game_id, language_code) DO NOTHING;
