INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Dangerous Hunts', 'Get ready for the next evolution in hunting games! The animals now want to get even. Cabela''s Dangerous Hunts delivers intense action in exotic locations through out the globe featuring some of the world''s most ferocious animals on the planet! Encounter grizzly bears, rhinos, leopards, cape buffalo and many more, in palm sweaty heart pounding hunting action. You''ll soon realize first hand what every hunter fears most with terrifying "kill or be killed" hunting action never before released. Test your aim and nerves - hunt over 15 of the most feared animals in 11 exotic locations around the world.' FROM games WHERE igdb_id = 5763 ON CONFLICT (game_id, language_code) DO NOTHING;
