INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantastic Fortune 2', 'Fantastic Fortune 2 is a romance simulation game. In this otome game the protagonist is one of the three female characters: Aoi (16-year old priestess summoned from another world), Marine (15), or Aqua (13-year old with a memory loss). The story takes place in a fantasy setting and it unfolds during a seven month training period where you try to become a "Daughter of Star".' FROM games WHERE igdb_id = 163158 ON CONFLICT (game_id, language_code) DO NOTHING;
