INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Heat Major League Baseball 2004', 'High Heat has always been generous with features in its PC incarnation, and the console version has finally caught up to it. Boasting eleven different modes of play, HH 2004 takes several steps beyond the product offered last year and genuinely tries rather hard to push feature diversity. All the classics are here: Home Run Derby, Exhibition, All-Star Games, Batting Practice, Player Editing devices, and other such goodies await the gamers who patiently explore its every area. Perfect for two-player matches, Two-on-Two Showdown returns from last year''s PS2 version and presents itself as a console-exclusive option (you''re not going to find it in the GBA or PC versions at all).' FROM games WHERE igdb_id = 24089 ON CONFLICT (game_id, language_code) DO NOTHING;
