INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dear Boys: Fast Break!', 'Dear Boys: Fast Break! is a Japan-exclusive PlayStation 2 gem that brings the beloved manga series to life through an engaging 3-D basketball simulation. Released on September 18, 2003, by Konami and developed by KCEJ, it immerses players in the journey of Mizuho High School''s basketball team as they face off against rivals like Honmoku East and Tendōji High in a gripping story mode. With over 50 characters, a gallery mode for unlocking artwork, and a blend of realistic gameplay and dramatic cut-scenes, it’s a must-play for fans of the Dear Boys franchise and sports game enthusiasts alike, despite never leaving Japan."' FROM games WHERE igdb_id = 334860 ON CONFLICT (game_id, language_code) DO NOTHING;
