INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Counter-Strike Neo', 'Counter-Strike Neo is a Japanese arcade adaptation of Counter-Strike, the original Half-Life multiplayer modification. It was published by Namco and runs on a Linux system. The game features unique maps, factions, and settings, though the gameplay and the weapon lineups remain the same as other Counter-Strike games, only with a huge difference in visuals.' FROM games WHERE igdb_id = 76822 ON CONFLICT (game_id, language_code) DO NOTHING;
