INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ages 2500 Vol. 2: Monaco GP', 'Monaco GP is a remake of the original 1979 arcade release of Monaco GP, sporting vastly updated graphics and audio. There is an "original" mode which mimicks the arcade game, and a "grand prix" mode which adds fifteen new courses, multiple camera viewpoints, powerups and a jump button. There are a number of other gameplay changes in this mode, and multiplayer support.' FROM games WHERE igdb_id = 98915 ON CONFLICT (game_id, language_code) DO NOTHING;
