INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angel''s Feather', 'Angel''s Feather is a Japanese boys'' love visual novel game created by BlueImpact, which was originally released on April 25, 2003 for PC, and later ported to the PlayStation 2 by KID. It was adapted into an OVA, which was animated by Studio Venet. The game''s character designer is Yamamoto Kazue. In 2007, Media Blasters licensed the anime for Region 1 release.' FROM games WHERE igdb_id = 72737 ON CONFLICT (game_id, language_code) DO NOTHING;
