INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Jack: Rave Slaves', 'Samurai Jack: Rave Slaves was a Macromedia Shockwave Toonami game that was available to play on cartoonnetwork.com beginning in 2003. However, the game did not appear on toonami.com until 2004. The game is no longer available at cartoonnetwork.com, but has been archived by fans.' FROM games WHERE igdb_id = 203060 ON CONFLICT (game_id, language_code) DO NOTHING;
