INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Study Helpers Math Booster', 'JumpStart Study Helpers Math Booster is a JumpStart game released in 2003. It is geared to 1st - 5th Grades and intended to assist in practicing math problems. It is a sister game to JumpStart Study Helpers Spelling Bee.' FROM games WHERE igdb_id = 366185 ON CONFLICT (game_id, language_code) DO NOTHING;
