INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harbinger', 'A huge ship, known as the Harbinger, enters a solar system destroying planets and civilizations in its path. Survivors are taken aboard the havoc-wreaking ship to work in labor camps, or be unluckily sent off to the laboratories for vicious tests and experiments that often lead to insanity. Few have managed to escape into the deep, forgotten wasteland levels of the ship, where an underground society exists. They search for a means of escape while fighting for their survival with anything they can scavenge as they attempt to ward off the relentless patrols sent for them.' FROM games WHERE igdb_id = 51230 ON CONFLICT (game_id, language_code) DO NOTHING;
