INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marshie''s Malloween Mix-Up', 'This Halloween game was released at the same time as Malloween Commercial, and a week prior to 3 Times Halloween Funjob. It is similar to the game Ikaruga in that the player must master two different "colors" (in this case black and orange). To do so, the player must collect marshmallows of the same color as Marshie''s current aura while simultaneously avoiding marshmallows of the other color.' FROM games WHERE igdb_id = 203155 ON CONFLICT (game_id, language_code) DO NOTHING;
