INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-maze', 107158, '2003-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8gax.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsy78.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Maze', 'Also commonly known as "Scary Maze Game," it became popular around the early 2000s as a "screamer" prank to jump-scare people. Gameplay consists of avoiding touching the walls with your mouse cursor to reach the end of the maze. These walls get closer together after each level, making the path the player must travel through narrower.
