INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onsen mo Issho', 'The follow-up to "Typing with Toro," a typing tutor game based on the Japanese PlayStation game Doko Demo Issyo. This time Toro and his friends are heading to a hot springs resort and will require your conversational typing prowess along the way. New minigames include karaoke, word games, snowman building, and others.' FROM games WHERE igdb_id = 246072 ON CONFLICT (game_id, language_code) DO NOTHING;
