INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey to the Center of the Earth', 'Ariane, a young reporter, is suddenly swallowed by the earth while covering a story near the Sneffels volcano. When she awakens, she discovers the strangest landscapes and a host of unusual objects. Join Ariane as she explores an unkown world of fascinating and fantastical civilizations hidden beneath the surface of the Earth. Inspired by the Jules Verne classic!' FROM games WHERE igdb_id = 32597 ON CONFLICT (game_id, language_code) DO NOTHING;
