INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Elf Bowling', 'Super Elf Bowling (Elf Bowling 4) was a 3-dimensional upgrade of the original with more complicated ball control and a wider variety of backgrounds, elf antics and elf jokes. One could also play as a variety of characters, including Santa, Dingle, and Mrs. Kringle.' FROM games WHERE igdb_id = 51315 ON CONFLICT (game_id, language_code) DO NOTHING;
