INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ozzy & Drix', 'A 2D platformer with 3D elements, Ozzy & Drix is based on the hit cartoon series from the Kids'' WB! which in turn is based on the movie Osmosis Jones. Join the gross-out adventures of a white blood cell "cop," Ozzy, and his over-the-counter cold pill sidekick, Drix. Fans of the hit series will now be part of the action on Game Boy Advance. Whiz down a blood cell highway in the "Cel Camino," provide protection from the dreaded "Phlegm-alanche," face off against nemesis Spryman and Gluteus and more as Ozzy & Drix live and play in their world inside teenage boy Hector Cruz.' FROM games WHERE igdb_id = 49318 ON CONFLICT (game_id, language_code) DO NOTHING;
