INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cambrian QTS: Kaseki ni Natte mo', 'Cambrian QTS - Kaseki ni Nattemo is an adventure game that is about a strange creatures that became extinct long ago that are discovered by chance in the South Pacific last year, they were successfully commercialized as pets with the name of Cambrian QTS. The new species grows into an aquarium filled with special seawater, as they grow hatched from an egg.
