INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panda Golf 2', 'Panda Golf 2 is a Flash-based 2D golf game where the player must hit a golf ball towards the flag platform. As the game progresses, it introduces more obstacles such as trampolines, conveyor platforms, flamethrowers, and more. Players could also create their own in-game levels and share them on the Panda Golf website.' FROM games WHERE igdb_id = 261714 ON CONFLICT (game_id, language_code) DO NOTHING;
