INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.N. Angel: Crimson Wings', 'Kurenai no Tsubasa (紅の翼) is based on D.N. Angel manga and anime and game''s release coincides with the airing of the last episode of the anime TV series. In the game the player controls Daisuke Niwa, the protagonist of the series, who has inherited the ability, through family bloodline, to turn into a phantom thief. While the game features various CG events and typical visual novel character dialogue screens, core gameplay is done in 3rd-person isometric perspective where the player directly controls the protagonist. Voice-acting was done by the same actors from the anime TV series.' FROM games WHERE igdb_id = 67374 ON CONFLICT (game_id, language_code) DO NOTHING;
