INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polly Pocket!: Super Splash Island', 'Join Polly and her friends for a day of fun and surprises at Super Splash Island. In Polly Pocket, you can play games and go on water rides while gaining special skills. Collect power-ups and prizes to help Polly move faster, or gain skills in each race to earn tickets. Water-park activities include sliding through colored tubes, racing in bumper boats, playing minigames, and more. As you progress through each event, you''ll unlock dressing rooms full of fashion surprises. Polly Pocket also features two-player modes.' FROM games WHERE igdb_id = 49434 ON CONFLICT (game_id, language_code) DO NOTHING;
