INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Equestrian Showcase', 'Equestrian Showcase puts players in the saddle of their favorite show horses at three of the world''s most prestigious venues including the Kentucky Three Day Event, Badminton Horse Trials, and Burghley Horse Trials. A fourth event, the Sydney Horse Trials at the Sydney International Equestrian Center, can be unlocked by earning points during a full championship season at the other three venues. Events consist of three main challenges, Dressage, Cross Country, and Show Jumping, with specific scoring rules and penalties in each.
