INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugby League', 'NRL Rugby League is a New Zealand-developed rugby sports game in the tradition of console based sports titles. It features 30 licensed teams, several major leagues and interantional test matches, 25 realistic stadiums, commentary by Andrew Voss, variable weather conditions, and all the action on the field you would expect from a game based on the sport, including advanced moves such as offloads, fend offs, side steps and dummy passes. You can create your own players, teams and competitions, with detailed statistics, and you have to take injuries, sin bins and send offs into account.' FROM games WHERE igdb_id = 6021 ON CONFLICT (game_id, language_code) DO NOTHING;
