INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Break in the Road', 'The perfect game for DJs, dance floor fanatics, or anybody who loves fresh beats. You play an aspiring DJ who gets the break of a lifetime - it''s up to you to write a hot, new dance track for a huge party. Problem is, the party is tonight! So, hit the streets of London with your sampler and grab some ''sounds of the street'' to mix into a new song.' FROM games WHERE igdb_id = 300000 ON CONFLICT (game_id, language_code) DO NOTHING;
