INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Sword and Fairy 2', 'The Legend of Sword and Fairy 2 is an action role-playing game developed by the DOMO group (known for its role in developing the Xuan-Yuan Sword video game series) and the now defunct Crazy Boys group under the Taiwanese company Softstar Entertainment. It is the second installment in The Legend of Sword and Fairy (or Chinese Paladin) video game series, and serves as a sequel to the first game. The game incorporates elements of wuxia, shenmo and fantasy.' FROM games WHERE igdb_id = 78448 ON CONFLICT (game_id, language_code) DO NOTHING;
