INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abashera', 'Abashera is a first person maze/platform game. Your mission is to find, and sometimes activate, the exit by solving different tasks. The maps are filled with very single minded creatures and much of the point of the game is to learn these creatures behaviors. Different dogs eat each other, frogs jump when you move in front of them, you can kill green dogs by falling on them, etc.' FROM games WHERE igdb_id = 71108 ON CONFLICT (game_id, language_code) DO NOTHING;
