INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mojo!', 'The Mojo! game is a challenging, graphically stunning and addictive 3D puzzle adventure that tests both your mind and your reflexes. Because your "Mojo" (energy) drains over time, you must quickly maneuver through progressively difficult stages, clearing sequences of colored blocks in increasingly shorter amounts of time. Only the most skilled players will be able to navigate Mojo!''s mind-bending chain of puzzles in order to survive to the legendary 100th stage!' FROM games WHERE igdb_id = 5931 ON CONFLICT (game_id, language_code) DO NOTHING;
