INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zoids-vs-ii', 50585, '2003-09-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ufr.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoids VS II', 'The release of Zoids VS II brought about several improvements to the game, including better landscape graphics, more Zoids, and a new user-interface. It also featured the new fist mode, engaging players at close-quarters combat. Released in Japan on September 4, 2003. The game included a variety of pilots, Zoids, weapons, and parts. Over 50 pilots were available to play as, including characters from Zoids: New Century and Chaotic Century. A large number of Zoids were included in the game including more than 60 Zoids and secret unlockable Zoids. By using a memory card containing data from the original Zoids VS, a Shield Liger DCS-J was available in the shop, which was otherwise unusable.
