INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chocolat: Maid Cafe "Curio"', 'The main character''s father suddenly gets remarried without noticing him, and he starts a new life with his father, a new mother and a younger sister, Suzu. But his new parents go on honeymoon for three months, and he is forced to work at his father''s coffee shop until they come back. He is totally confused with his new life at first. But he meets various girls, falls in love and gradually starts to enjoy his life....' FROM games WHERE igdb_id = 194712 ON CONFLICT (game_id, language_code) DO NOTHING;
