INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5 Spots', 'Can you spot the difference between two seemingly identical images? Can you do it in a limited amount of time? This electronic version of a classic family puzzler pits your eyes against your expectations as you try to spot the differences. Featuring tons of images, and random changes, there''s no end to the fun.' FROM games WHERE igdb_id = 94277 ON CONFLICT (game_id, language_code) DO NOTHING;
