INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ford Truck Mania', 'Pilot tough Ford Trucks across challenging terrain in this Gotham Games release for PlayStation. Gamers choose from a variety of vehicles, including eight standard Fords and four modified trucks, all with adjustable steering, transmission, tires, suspension, and even color. Races are run in three circuits, Amateur, Semi Pro, and Professional, and a number of options allow players to customize courses and rules to suit their preferences.' FROM games WHERE igdb_id = 44942 ON CONFLICT (game_id, language_code) DO NOTHING;
