INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cruise Ship Tycoon', 'Cruise Ship Tycoon is a fun and exciting simulation game that lets you take control of a fleet of cruise ships. Features include: colorful and unique characters (including staff and passengers), Challenge, Career and Open Play game modes, various locations ranging from Antarctica to Alaska and Russia to Mexico. There are 4 base model ships to choose from and a large variety of rooms, food, staff and entertainment buildings to create. Don''t forget to steer your ship clear of icebergs, land and those pesky sea creatures.' FROM games WHERE igdb_id = 50394 ON CONFLICT (game_id, language_code) DO NOTHING;
