INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legacy of Flan 3: Storm of Hades', 'Legacy of Flan 3 : Storm of Hades is the third installment in the Legacy Of Flan series, created by Scott Cawthon. The game was an MMORPG, which means the game was online. It was created using the Moo2 extension in the software Multimedia Fusion. Unfortunately, the servers for this game were shut down a long time ago, making the game unplayable. However, somebody discovered a way of fixing the game.' FROM games WHERE igdb_id = 284182 ON CONFLICT (game_id, language_code) DO NOTHING;
