INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minna no Soft Series: Tetris Advance', 'Minna no Soft Series: Tetris Advance, known in-game simply as Tetris Advance, is a falling-block puzzle game. Part of Success''s Minna no Soft series, Tetris Advance includes the standard game of Tetris along with a mission-based "Challenge" mode that tasks players with completing specific objectives (such as erasing lines, or clearing an entire board with a certain piece arrangement). It also includes linked Single-Pak Multiplayer support for up to four players.' FROM games WHERE igdb_id = 49724 ON CONFLICT (game_id, language_code) DO NOTHING;
