INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Cars 2', 'Tiny Cars 2 is a thrilling and fast-paced racing game that challenges players to navigate through intricate tracks with miniature vehicles, testing their strategic driving skills and reflexes. Experience the adrenaline rush of high-speed chases and tight cornering as you race against time and opponents, with vibrant graphics and engaging gameplay that keep you on the edge of your seat.' FROM games WHERE igdb_id = 70732 ON CONFLICT (game_id, language_code) DO NOTHING;
