INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vajimon', 'The last title developed by Guillotine was the network-strategy nonsense game Vajimon, which saw players fight against each other over the internet using a variety of vegetables. Around 2003, the company''s operations were terminated and its managers retired. The game servers were later briefly brought back online in 2012 for some time, but went under again afterwards.' FROM games WHERE igdb_id = 145775 ON CONFLICT (game_id, language_code) DO NOTHING;
