INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 43624 AND rs.code = 'ESRB' AND r.code = 'E' ON CONFLICT DO NOTHING;
