INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Genesis Evangelion 2', 'Neon Genesis Evangelion 2 (新世紀エヴァンゲリオン2 lit. "Shinseiki Evangelion 2") is a Japanese video game for the PlayStation 2 developed by Alfa System and published by Bandai. It has role-playing video game and world-controlling elements, and allows the player to follow a number of characters (such as Asuka Langley Soryu, Shinji Ikari, Pen², etc.) through multiple versions of the main plot of the anime Neon Genesis Evangelion. The PlayStation Portable port was released 2006-04-27 as Neon Genesis Evangelion 2 -Another Cases-' FROM games WHERE igdb_id = 75876 ON CONFLICT (game_id, language_code) DO NOTHING;
