INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Classroom', 'In The Classroom, the player controls a high school student called Alex who is in his last ten days of school and has to take an exam on each of those days. However, Alex does not study and would rather risk cheating to perform well in his exams. In each of the ten levels in the game, the player must fill their cheat meter completely by moving next to smart students (who are represented by yellow circles) and holding the left mouse button.' FROM games WHERE igdb_id = 242160 ON CONFLICT (game_id, language_code) DO NOTHING;
