INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'P.T.O. IV', 'From Midway to the Mediterranean, every conquest brings you closer to victory in P.T.O. IV. Set during WWII, this game puts you in charge of US, Japanese, German, or British forces in missions to storm enemy garrisons. In more than 15 regional and two global campaigns, your missions include striking Leyte Gulf and establishing supply lines, ordering German Wolfpack ops in the North Sea, and launching Royal Navy cruisers to intercept Japanese dive-bombers. History is in your hands as you lead 100 battleships into combat while dispatching spies, disrupting trade, and realigning nations.' FROM games WHERE igdb_id = 43435 ON CONFLICT (game_id, language_code) DO NOTHING;
