INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gods-and-generals', 73662, '2003-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93n9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fxvgvsr2bd4nmylvkwix.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gods and Generals', 'Gods and Generals is a historical first-person shooter video game developed by Activision Value and published by Activision. The game is based on the film of the same name. The player commands a soldier in the midst of the American Civil War, choosing either to side with the Union or the Confederacy, and plays alongside hordes of other soldiers. The player is tasked with various missions such as raids and reconnaissance, in addition to leading a full army company. In large-scale battles ranging from the Second Battle of Bull Run, the battle of Chancellorsville and the battle of Fredericksburg, players are equipped with muskets, revolvers, sabers and other weapons. This nine-part campaign game uses various scenes from the film.
