INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('return-of-egypt', 106670, '2003-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hvzolc37wrnyoegl5p8z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scufso.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return of Egypt', 'Return of Egypt is a very good Castlevania clone from Driven Phantom Soft, sporting fluid 2D sidescrolling action, plenty of well-drawn enemies, and excellent level design. You star Moses as he returns to Egypt to battle various undeads and even Egyptian gods. Similar to the hero in Castlevania, Moses wields a whip in this game as his default weapon. The castle is very well-designed, full of traps, optional routes, and secret rooms. Similar to most console platformers, you cannot save at any point in the game, but only at "save points" - which are conveniently placed every few rooms apart. One thing I like is the number of "special skills" and magic spells you will acquire as you play through the game, usually after beating each "boss" monster. Examples of these skills are rapid run and magical storm.' FROM games WHERE igdb_id = 106670 ON CONFLICT (game_id, language_code) DO NOTHING;
