INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Country: Barrel Maze', 'Donkey Kong Country: Barrel Maze, or Donkey Kong Barrel Maze, is a browser game developed by Skyworks Interactive (formerly Skyworks Technologies) and published on their website, Candystand.com, under Nintendo''s endorsement. It requires Adobe Shockwave to run. The game is based on elements from Donkey Kong Country and has Donkey Kong in a quasi-starring role, with Diddy Kong and Cranky Kong only making cameo appearances on the title and loading screens. The player controls a barrel loaded with bananas and has to roll it through a series of obstacles to reach DK at the end of every stage in the game.' FROM games WHERE igdb_id = 231637 ON CONFLICT (game_id, language_code) DO NOTHING;
