INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motocross Mania 2', 'Motocross Mania 2 brings the reckless action of motocross racing back to the PlayStation. Players will experience improved turning, refined graphics, advanced bikes, new stunts, two classes of bikes (125cc or 250cc), and three levels of difficulty spread across 16 tracks. Devoted motocross racers can develop their own tracks with the Edit Track option.' FROM games WHERE igdb_id = 45100 ON CONFLICT (game_id, language_code) DO NOTHING;
