INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slouching Towards Bedlam', 'Enter a steampunk adventure set in a London that might have been. The year is 1885. Bedlam Hospital still stands in Moorsfield, a decaying shell used to house the poor and the hopeless. Steam-driven mechanical wonders roam the streets. Gear-wheeled analytical engines spin out reams of thought onto punched paper tapes. And in the darkness – in the alleys and the side shops – hide secrets. A piece of interactive fiction written by Star Foster and Daniel Ravipinto.' FROM games WHERE igdb_id = 60141 ON CONFLICT (game_id, language_code) DO NOTHING;
