INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'America''s Army 2', 'America''s Army (also known as AA or America''s Army Game Project) is a series of video games and other media developed by the United States Army and released as a global public relations initiative to help with recruitment. America''s Army was conceived by Colonel Casey Wardynski and is managed by the U.S. Army''s Office of Economic and Manpower Analysis at the United States Military Academy. Wardynski envisioned "using computer game technology to provide the public a virtual Soldier experience that was engaging, informative and entertaining' FROM games WHERE igdb_id = 15820 ON CONFLICT (game_id, language_code) DO NOTHING;
