INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lolagame', 'Lola Game is a management and simulation game with an isometric perspective. It is a game commissioned by Granarolo, an italian multinational company that operates in the fresh milk and diary-cheese sector. It was released as a free-to-play game on their website alongside a prize competition. The goal of the game is to be able to produce 310 litres of milk every month from the best breed of cows. The player starts in march 2003 with just 3 brown cows, 1 bull and 950 euros.' FROM games WHERE igdb_id = 320294 ON CONFLICT (game_id, language_code) DO NOTHING;
