INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Beach Soccer', 'Billed as the first Beach Soccer video game designed especially for fans of soccer and extreme sports, Ultimate Beach Soccer offers five-on-five action with lots of aerial passes, special moves, combos, intense shooting and scoring, spectacular goals and saves. Set in unique and exotic locations spanning the globe, including Rio, France, Japan and Venice Beach, California, Ultimate Beach Soccer offers detailed and exotic stadiums, with daytime and nighttime games, including spectacular pitch-side shows with DJs, cheerleaders and commentators all fully modeled and animated in-game. Game modes range from quick match to long-term competitions and custom tournaments. The game sports the Official Beach Soccer Federation License - Real Players, Real Teams and Real Locations.' FROM games WHERE igdb_id = 49353 ON CONFLICT (game_id, language_code) DO NOTHING;
