INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CT Special Forces: Back to Hell', 'Intelligence agencies are mentioning an increase in terrorist activity in every nook and cranny of the planet. The secret services are in a decidedly uncomfortable spot, given the latest resounding failures. The CT Special Forces unit will once again be called upon to diffuse a series of conflicts that have democracies around the globe highly concerned.' FROM games WHERE igdb_id = 45103 ON CONFLICT (game_id, language_code) DO NOTHING;
