INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warblade', 'Warblade is a shareware computer game for Microsoft Windows and OS X, written by Norwegian developer Edgar M. Vigdal. The Windows version runs well on Linux under Wine. It is also available for retail in the App Store for iOS devices (in iPhone/iPod Touch and iPad versions). The game is a 2D space shooter in the vein of the perennial classic Galaga. It is a rewrite and modernization of a popular Amiga shareware game, Deluxe Galaga, which was written by the same author back in the mid-1990s. Where technically possible, the graphics and sounds are respectful to their Amiga origins.' FROM games WHERE igdb_id = 128358 ON CONFLICT (game_id, language_code) DO NOTHING;
