INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow', 'The story of Snow starts when the main protagonist Izumo Kanata visits a small village called Ryujinmura (village of the dragon god) to help his cousin Tsugumi manage a local hotel with hot springs. In the village there is an old legend: In ancient times, the village is protected by the dragon goddess. However, one day the dragon goddesses fell in love with a human, which is strictly forbidden, and this incident finally caused the village to be always covered by snow after that. The game then tells the daily life of the protagonist in the village, and finally links the story to the legend of dragon goddess.' FROM games WHERE igdb_id = 221025 ON CONFLICT (game_id, language_code) DO NOTHING;
