INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VeggieTales Creativity City', 'VeggieTales Creativity City is a PC game released in 2003. Make your own invitations, thank you cards, greeting cards, stationery, e-cards and more! Design storybooks and electronic books to send to family. Create photoframes, bookmarks, notepads, coloring pages, calendars and more. Design mazes, connect-the-dots, card games, puzzles, stickers and a Pin the Tooth on Larry party game. Create an amazing "photo mosaic" of your own face, then use your imagination to create electronic posters.' FROM games WHERE igdb_id = 124319 ON CONFLICT (game_id, language_code) DO NOTHING;
