INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wind: A Breath of Heart', 'Originally released for PC (Windows) under the same title as an adult visual novel, the game was then ported to consoles with removed adult contents, but also with additional CG events and story elements added to compensate for the lack of erotic scenes. The game follows Makoto Okano as he returns to his hometown after 10 years away. Before he left, he and Minamo Narukaze made a promise to each other to meet again. She told him she will keep on playing the harmonic and even though he may be too far away to see it, the wind will carry the melody, hopefully all the way to his place.' FROM games WHERE igdb_id = 161174 ON CONFLICT (game_id, language_code) DO NOTHING;
