INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AMF Bowling 2004', 'Bowling fans can appreciate AMF Bowling 2004''s realistic sound effects, array of gameplay options, and accurate ball, pin, and lane physics. This bowling simulation also lets you create your own bowler and customize your ball''s weight, color, and texture. In multiple gameplay modes, such as practice and tournament play, you can find that perfect combination of position, speed, and ball velocity. Showcase your skills against professional bowlers or against a friend.' FROM games WHERE igdb_id = 5723 ON CONFLICT (game_id, language_code) DO NOTHING;
