INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baldr Force Exe', 'Baldr Force Exe is an enhanced release of Baldr Force. It adds a new weapon (gravity field), a "very easy" difficulty level, and a Hell Mode, which puts the player in a row of increasingly challenging battles. The PlayStation 2 version also adds Hyper and Time Attack gameplay modes, voice-overs, and a new intro. The Windows release retains the explicit sex scenes, while the console releases removes them.' FROM games WHERE igdb_id = 44622 ON CONFLICT (game_id, language_code) DO NOTHING;
