INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1942 Wing Baron', 'Jump on board of the famous red biplane and destroy everything you come across! If you enjoy classic aviation arcade games in which your screen fills up with chaos and destruction you’ll love 1942 Wing Baron. Progress through 15 levels with different landscapes and lots of enemies who will make your life a misery: planes, ships, tanks, helicopters, etc. Pick up arms, avoid enemy bursts of machine-gun fire and confront the most dangerous final bosses!' FROM games WHERE igdb_id = 159403 ON CONFLICT (game_id, language_code) DO NOTHING;
