INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanyo Pachinko Paradise 8: Shin Umi Monogatari', 'Pachinko Paradise 8 is one of the many titles in Irem''s long-running pachinko simulation series. It features a faithful 3D recreation of the CR Shin Umi Monogatari M27 pachinko machine made by Sanyo Bussan. There are two modes available: Tsūjō (Normal) mode allows the player to modify a wide range of settings for each machine, while Jissen (Battle) mode challenges the player to win as many balls as possible on the default settings with a limited starting pool and time limit. There is also a View mode where the various animations that play on the in-game display can be freely viewed.' FROM games WHERE igdb_id = 60901 ON CONFLICT (game_id, language_code) DO NOTHING;
