INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RPG Workshop Max 2', 'This is an updated version of RPG Max that includes a folder with over 25 great clipart images - including heros, backgrounds, friends and foes. The battle graphics have been improved, along with a cleaner layout, and several bugs have been fixed from previous versions. This is still novelty software, though, and probably could not be used to create a commercial game. This should be used as a practice tool for those starting off in game programming.' FROM games WHERE igdb_id = 262444 ON CONFLICT (game_id, language_code) DO NOTHING;
