INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golf Adventure Galaxy', 'So you''ve surpassed the sandtraps and ditched the knickers. Here''s great news for golfers who have conquered the world! Go outer-limits and trek through odd, lovely worlds in a virtual Golf Galaxy. The universe awaits in this beautiful 3D mini-golf game with 25 celestial holes! Solve puzzles, avoid traps, play special boss levels, and venture where no golfer has ever gone! Stunning 3D visuals, directional sound, and amazing soundtracks enhance this orbital game!' FROM games WHERE igdb_id = 74013 ON CONFLICT (game_id, language_code) DO NOTHING;
