INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Korea: Forgotten Conflict', 'A stealth game based on the Commandos gameplay style of interdependent characters solving puzzles based mainly on stealth. The player receives a number of commandos each mission and they have some special abilities (medic, sniper, engineer, spy and assassin), with the main gameplay focusing on inventory management and basic combat. Stealth is rudimentary and doesn''t affect the mission beyond enemies trying to attack the player''s units' FROM games WHERE igdb_id = 24186 ON CONFLICT (game_id, language_code) DO NOTHING;
