INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal II: The Awakening - Special Edition', 'The Unreal adventure continues with the release of the action shooter Unreal II: The Awakening. Along the outer edge of space, you are plunged into a desperate mission to kill all comers--alien and otherwise--and prevent the awakening of an evil force. Unreal II: The Awakening includes adrenaline-pumping destruction and impressive visuals in a variety of missions. Now, through scorching heat, over icy terrain, and within eerie alien cities, are you ready to launch into battle?' FROM games WHERE igdb_id = 46625 ON CONFLICT (game_id, language_code) DO NOTHING;
